node -e "
const fs = require('fs');
const s = JSON.parse(fs.readFileSync('.v1/state.json', 'utf8'));
s.hypotheses = [
  {
    id: 'hyp-4cba780f',
    description: 'convertCurrency in src/money.ts uses Math.floor(converted * 100) / 100 which truncates toward zero. A value like 92.349999... (JS result of 100 * 0.9235) becomes 92.34 instead of 92.35. The file already defines roundToCents and uses it for add/subtract/multiply; convertCurrency is the only outlier and even carries a // BUG: truncates instead of rounding comment. Fix: replace Math.floor(...)/100 with roundToCents(converted).',
    evidence: [
      'src/money.ts:convertCurrency returns Math.floor(converted * 100) / 100',
      'src/money.ts:inline comment // BUG: truncates instead of rounding above buggy line',
      'src/money.ts:roundToCents helper exists and is used by add/subtract/multiply/createMoney',
      'tests/money.test.ts:convertCurrency precision test assumes correct rounding',
      'repro: 100*0.9235 = 92.34999999999999 in JS; old code -> 92.34; roundToCents -> 92.35'
    ],
    confidence: 0.99,
    status: 'selected',
    files: ['src/money.ts', 'tests/money.test.ts']
  }
];
s.selectedHypothesis = 'hyp-4cba780f';
fs.writeFileSync('.v1/state.json', JSON.stringify(s, null, 2));
const verify = JSON.parse(fs.readFileSync('.v1/state.json', 'utf8'));
console.log('hypotheses after write:', verify.hypotheses.length, verify.selectedHypothesis);
"

